/**
 * Exercise image resolution for the LIFT knowledge base.
 *
 * KB entries carry an `image` field like `assets/exercises/<slug>.png`.
 * Metro/Expo cannot `require()` a dynamic path, so this module keeps a
 * static registry of the image files actually bundled in `assets/exercises/`.
 * Anything not in the registry (e.g. an exercise whose AI-generated image
 * hasn't landed yet) falls back to the neutral placeholder — no exercise
 * ever renders an empty image frame.
 *
 * The REGISTRY block is generated by `scripts/gen-exercise-image-registry.mjs`.
 * Re-run that script after adding real per-exercise images.
 */

// @ts-ignore - PNG asset modules are declared in ./exercise-images.d.ts
const placeholder = require('../../assets/exercises/placeholder.png');

// === BEGIN GENERATED REGISTRY ===
const REGISTRY: Record<string, unknown> = {
  'assets/exercises/placeholder.png': require('../../assets/exercises/placeholder.png'),
};
// === END GENERATED REGISTRY ===

/**
 * Resolve a KB exercise `image` path to a bundled asset source usable as an
 * `<Image source={...}>` prop. Falls back to the placeholder when the path
 * is missing, empty, or not bundled.
 */
export function resolveExerciseImage(image?: string | null): unknown {
  if (image && REGISTRY[image]) return REGISTRY[image];
  return placeholder;
}

/**
 * True when the exercise has a real bundled image (not the placeholder).
 * Useful for "image coming soon" affordances.
 */
export function hasExerciseImage(image?: string | null): boolean {
  return !!image && !!REGISTRY[image] && image !== 'assets/exercises/placeholder.png';
}

/** Direct access to the placeholder asset. */
export function placeholderImage(): unknown {
  return placeholder;
}
